// Chapter-12 identification (鉴定) for the Pathfinder Spy (enemy_1314_wdnjd, _2), the Sentry Spy (enemy_1315_wdyjd, _2)
// the Armed Spy (enemy_1316_wdpjd, _2) and the Norport Civilian (enemy_1313_wdfmr, _2). Research and sources: docs/CHAPTER-12-IDENTIFICATION-RESEARCH.md.
// - Phase 1 (…[detect_p1], every 0.1 s): +2 if blocked (CheckBlocked) or on a tile currently in own-side sight
//   (KEEP_REVEALED), otherwise -1 (cap 301). At >= 300, phase 2 (…[detect_p2]): +3 / -1, never back to phase 1.
//   At >= 300 identification completes and `unit_mainline12[detecting]` ends. A disappeared unit loses a stack.
// - Spy: before, `enemy_mainline12[civilianMode]` (INVINCIBLE), an empty combat (blockable, never attacks) and the _A
//   clips. On completion, switchModeTrigger (FORCE_DISARMED, INVINCIBLE, UNMOVABLE_PRIVATE) casts SwitchMode (Die_A)
//   and then switchMode moves him to mode 1: melee attacks, _B clips, moveSpeed +0.05 (ADDITION) and the next attack
//   at EnhancedAttack.atk_scale (enemy_wdnjd[bonus_attack]: the flag ends after one attack or ability).
// - Civilian: `unit_mainline12[civilianMode]` (INVINCIBLE) throughout; blockable until confirmed. On completion,
//   civilian_mainline12[detectComplete] (BLOCK_FREE): reaching the exit runs ModifyMaxCost (civilianTalent.max_cost).
//   An unconfirmed civilian reaching the exit gives nothing; life cost 0.
import clocks from "../../data/arkpedia-norport-identity-animations.json" with{type:"json"};
import {sameOutcomeValue as same} from "./enemy-outcome-contracts.js";
const norm=v=>Array.isArray(v)?v.map(norm):v&&typeof v==="object"?("m_PathID"in v&&Object.keys(v).length===2?{ref:v.m_PathID==="0"?null:v.m_FileID===0?"local":"ext:"+v.m_PathID}
 :Object.fromEntries(Object.entries(v).filter(([k])=>!["m_GameObject","m_Name","m_Father","m_Children"].includes(k)).map(([k,x])=>[k,norm(x)]))):v;
const refs=v=>Array.isArray(v)?v.flatMap(refs):v&&typeof v==="object"?("m_PathID"in v&&v.m_FileID===0&&v.m_PathID!=="0"&&Object.keys(v).length===2?[v]
 :Object.entries(v).filter(([k])=>k!=="m_GameObject").flatMap(([,x])=>refs(x))):[];
function closure(n){
 const seen=new Set(),todo=Object.values(n).flat();
 while(todo.length){const c=todo.pop();if(!c||seen.has(c))continue;seen.add(c);todo.push(...n.$siblings(c),...refs(c).map(r=>n.$ref(r)).filter(Boolean));}
 return [...seen].map(c=>JSON.stringify(norm(c))).sort();
}
